import {canStand} from './room-core.mjs?v=p21-b407-s039-reuse';
const copy=v=>JSON.parse(JSON.stringify(v));
export function createGuildCampaign({makeStore,rooms,world,bindings=[],position,visits,steps,stop=()=>{},restore=()=>{},flagKey='guildInteriorsV1',acceptDoorState=(p,door)=>p[2]===door.edge,id=()=>{const bytes=new Uint32Array(4);crypto.getRandomValues(bytes);return [...bytes].map(v=>v.toString(16)).join("-");}}){
 const byId=new Map(rooms.map(r=>[r.id,r])),registered=new Map(bindings.map(b=>[b.doorID,b.roomID]));
 const validOutside=p=>Array.isArray(p)&&p.length===3&&p.slice(0,2).every(Number.isInteger)&&world.members.get(p.slice(0,2).join(','))?.has(p[2]);
 function read(){const store=makeStore(),value=store.read(),ledger=value.state.flags[flagKey]||{schema:1,rooms:{},active:null};if(ledger.schema!==1||!ledger.rooms||typeof ledger.rooms!=='object'||Array.isArray(ledger.rooms))throw Error('Unsupported interior record retained without changes');return {store,value,ledger};}
 function commit(ctx){ctx.value.state.flags[flagKey]=ctx.ledger;ctx.store.campaign(ctx.value.state);ctx.store.project();}
 function validate(roomID,snapshot){const room=byId.get(roomID);if(!room||snapshot?.schema!==1||snapshot.room!==roomID||!canStand(room,snapshot.position)||!Array.isArray(snapshot.examined))throw Error('Invalid interior position or room record');return {schema:1,room:roomID,position:snapshot.position.slice(),examined:[...new Set(snapshot.examined.filter(x=>room.hotspots.some(h=>h.id===x)))]};}
 function assertDoor(doorID,roomID){const door=world.doors.get(doorID);if(registered.get(doorID)!==roomID||!door||door.held||!byId.has(roomID))throw Error('A confirmed available guildhouse door is required');return door;}
 function enter(doorID,roomID){const c=read();if(c.value.pending)throw Error('Finish the current incident before entering a guildhouse');if(c.ledger.active)throw Error('A guildhouse visit is already active');const door=assertDoor(doorID,roomID),p=position();if(!validOutside(p)||Math.hypot(p[0]-door.position[0],p[1]-door.position[1])>1.6||!acceptDoorState(p,door))throw Error('Walk to this guildhouse entrance first');const prior=c.ledger.rooms[roomID];if(prior)validate(roomID,prior);stop();const token=id();c.store.navigation(p,visits(),steps());const latest=read();latest.ledger.active={schema:1,id:token,roomID,doorID,returnPosition:p.slice()};commit(latest);return {id:token,roomID,snapshot:prior?copy(prior):null};}
 function active(){const c=read(),a=c.ledger.active;if(!a)return null;if(a.schema!==1||typeof a.id!=='string')throw Error('Unsupported active visit retained');assertDoor(a.doorID,a.roomID);if(!validOutside(a.returnPosition))throw Error('Saved exterior return cell is unavailable');const snapshot=c.ledger.rooms[a.roomID];if(snapshot)validate(a.roomID,snapshot);return {...copy(a),snapshot:snapshot?copy(snapshot):null};}
 function save(token,snapshot){const c=read(),a=c.ledger.active;if(!a||a.id!==token)throw Error('Stale guild visit');c.ledger.rooms[a.roomID]=validate(a.roomID,snapshot);commit(c);}
 function finish(token,snapshot){const c=read(),a=c.ledger.active;if(!a||a.id!==token)return false;const s=validate(a.roomID,snapshot),r=byId.get(a.roomID);if(Math.hypot(s.position[0]-r.entry[0],s.position[1]-r.entry[1])>.000001)throw Error('Return to the interior entrance before leaving');if(!validOutside(a.returnPosition))throw Error('Saved exterior return cell is unavailable');c.ledger.rooms[a.roomID]=s;c.ledger.active=null;c.store.navigation(a.returnPosition,c.value.visited,c.value.steps);commit(c);restore(a.returnPosition.slice());return true;}
 function knownVisit(a){if(!a||a.schema!==1||typeof a.id!=='string'||!a.id||!byId.has(a.roomID)||registered.get(a.doorID)!==a.roomID)throw Error('Unsupported active visit retained');return a;}
 function recoveryFor(c,roomID){const a=c.ledger.active;if(a)knownVisit(a);const target=roomID||a?.roomID;if(!byId.has(target)||a&&a.roomID!==target||!a&&c.value.pending)return null;if(a&&!validOutside(a.returnPosition))throw Error('Saved exterior return cell is unavailable');const record=c.ledger.rooms[target];if(!record)return null;if(record.schema!==1||record.room!==target||!Array.isArray(record.examined))throw Error('Unsupported room record retained');if(canStand(byId.get(target),record.position))return null;if(!canStand(byId.get(target),byId.get(target).entry))throw Error('The current room entrance is unavailable');return {roomID:target,visitID:a?.id||null,fingerprint:JSON.stringify(record)};}
 function recovery(roomID){return recoveryFor(read(),roomID);}
 function repair(roomID,fingerprint){const c=read(),offer=recoveryFor(c,roomID);if(!offer||offer.fingerprint!==fingerprint)throw Error('The saved room changed; review recovery again');if(c.ledger.recoveryArchive!==undefined&&!Array.isArray(c.ledger.recoveryArchive))throw Error('Unsupported recovery archive retained');const original=c.ledger.rooms[roomID];c.ledger.recoveryArchive=[...(c.ledger.recoveryArchive||[]),{roomID,reason:'saved-position-no-longer-clear',original:copy(original)}];c.ledger.rooms[roomID]=validate(roomID,{...original,position:byId.get(roomID).entry});commit(c);return copy(c.ledger.rooms[roomID]);}
 function cancel(token){const c=read(),a=c.ledger.active;if(!a||a.id!==token)return false;knownVisit(a);if(!validOutside(a.returnPosition))throw Error('Saved exterior return cell is unavailable');c.ledger.active=null;c.store.navigation(a.returnPosition,c.value.visited,c.value.steps);commit(c);restore(a.returnPosition.slice());return true;}
 return Object.freeze({enter,active,save,finish,cancel,recovery,repair,roomRecord:roomID=>{const r=read().ledger.rooms[roomID];return r?validate(roomID,r):null;}});
}
